JS=r'''<script>(function(){const root=document.getElementById('liveNav');if(!root)return;const wraps=[...root.querySelectorAll('.stream-wrap')];let target=0,current=0,raf=0;function read(){const r=root.getBoundingClientRect(),span=Math.max(1,root.offsetHeight-innerHeight);target=Math.min(1,Math.max(0,-r.top/span));if(!raf)raf=requestAnimationFrame(tick)}function tick(){current+=(target-current)*.085;const vw=innerWidth;wraps.forEach((s,i)=>{const speed=parseFloat(s.dataset.speed||.15),origin=parseFloat(s.dataset.origin||0);const direction=i===1?1:-1;const distance=vw*(.72+speed*1.8);const x=vw*origin+direction*current*distance*speed*2.45;s.style.setProperty('--scroll-x',x.toFixed(2)+'px')});if(Math.abs(target-current)>.0006){raf=requestAnimationFrame(tick)}else{current=target;raf=0}}addEventListener('scroll',read,{passive:true});addEventListener('resize',read);read()})();</script>'''

def render(edit=False):
    html=c01.render(edit=edit)
    html=html.replace('</style>',CSS+'</style>',1)
    marker='<section class="world dark">'
    html=html.replace(marker,NAV+marker,1)
    html=html.replace('</body>',JS+'</body>',1)
    html=html.replace('<title>Living Water · Candidate 01</title>','<title>Living Water · Candidate 04</title>',1)
    html=html.replace('DORÉ DESIGN · LIVING WATER · CANDIDATE 01','DORÉ DESIGN · LIVING WATER · CANDIDATE 04',1)
    return html
